{
  "category_edits": [
    {
      "category": "sequence_interest",
      "rationale": "Test broader interest retention across all four datasets by increasing causal pooling weight to 0.3 and half-life to eight interactions. Preserve padding exclusion, causal prefixes, final-real-position inference, and the existing GRU architecture and training configuration.",
      "edits": [
        {
          "find": "        weights = torch.exp2(-distances.clamp(min=0).to(out.dtype) / 4.0)",
          "replace": "        weights = torch.exp2(-distances.clamp(min=0).to(out.dtype) / 8.0)"
        },
        {
          "find": "        return (0.8 * out + 0.2 * mean) * real",
          "replace": "        return (0.7 * out + 0.3 * mean) * real"
        },
        {
          "find": "            \"sequence_readout\": \"gru_0.8_causal_mean_0.2_half_life_4\",",
          "replace": "            \"sequence_readout\": \"gru_0.7_causal_mean_0.3_half_life_8\","
        },
        {
          "find": "        if meta.get(\"sequence_readout\") != \"gru_0.8_causal_mean_0.2_half_life_4\":",
          "replace": "        if meta.get(\"sequence_readout\") != \"gru_0.7_causal_mean_0.3_half_life_8\":"
        }
      ]
    }
  ],
  "change_summary": "Use 0.7 GRU state plus 0.3 causal interest mean with half-life eight during training and inference. Update checkpoint metadata and generated predictor validation consistently; retain one model per category."
}
